let
  # Samba share defaults shared by the fast, docs, vault and bulk shares.
  groupShare = path: extra: {
    inherit path;
    "valid users" = "@shared";
    "force user" = "quill";
    "force group" = "shared";
    "read only" = "no";
    "create mask" = "0660";
    "force create mode" = "0660";
    "directory mask" = "2770";
    "force directory mode" = "2770";
  } // extra;
in
